import {controlIdentity,useScopedControl,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
import {useRef} from 'react';
import {Modal,Text,View} from 'react-native';
import {createStore,type StoreApi} from 'zustand/vanilla';
import {useStore} from 'zustand';
import {Button} from '@/components/nyc-tron/ui/components/Button';
import {joinClasses} from '@/components/nyc-tron/ui/components/styles';
import {recoveryMessage,recoveryTitle,type AudioRecoveryNotice} from '@/components/nyc-tron/ui/components/forge/audio/audio-recovery-model';

type Action=()=>void|Promise<unknown>;
type Base=ScopedControlProps&{readonly visible:boolean;readonly onClose:()=>void;readonly error?:string;className?:string;unstyled?:boolean};
/** Host callbacks are required for each recovery kind; no automatic resume or fabricated recovery file. */
export type AudioInterruptionRecoveryDialogProps=Base&(
 {readonly notice:Extract<AudioRecoveryNotice,{kind:'paused'}>;readonly onResume:Action;readonly onStop:Action}|
 {readonly notice:Extract<AudioRecoveryNotice,{kind:'reset'}>;readonly onRetry:Action;readonly onStop:Action}|
 {readonly notice:Extract<AudioRecoveryNotice,{kind:'recording'}>;readonly onKeep:Action;readonly onDiscard:Action});
/** Explicit recovery decisions; rejected actions keep the dialog open with the error. */
export function AudioInterruptionRecoveryDialog({scope='audio-recovery',revision=0,...props}:AudioInterruptionRecoveryDialogProps){
 const owner=JSON.stringify([...controlIdentity(scope,revision),props.visible,props.notice,props.disabledReason]),guard=useScopedControl(owner,props,!props.visible||props.disabledReason!==undefined);
 const invoke=async(action:(host:typeof props)=>unknown)=>{let failure:unknown;const ok=await guard.run('recovery',async h=>{try{return await action(h);}catch(error){failure=error;throw error;}});if(ok!==true)throw failure??new Error('Audio recovery action was not completed');};
 return <AudioRecoveryBody key={owner} {...props} onClose={()=>guard.current()?.onClose()}
 {...('onKeep' in props?{onKeep:()=>invoke(h=>'onKeep' in h?h.onKeep():undefined),onDiscard:()=>invoke(h=>'onDiscard' in h?h.onDiscard():undefined)}:'onRetry' in props?{onRetry:()=>invoke(h=>'onRetry' in h?h.onRetry():undefined),onStop:()=>invoke(h=>'onStop' in h?h.onStop():undefined)}:{onResume:()=>invoke(h=>'onResume' in h&&h.notice.kind==='paused'&&h.notice.ready?h.onResume():Promise.reject(new Error('Audio is not ready'))),onStop:()=>invoke(h=>'onStop' in h?h.onStop():undefined)})}/>;
}
function AudioRecoveryBody(props:AudioInterruptionRecoveryDialogProps){
 const local=useRef<StoreApi<{busy:boolean;error:string|undefined}>|null>(null);if(!local.current)local.current=createStore(()=>({busy:false,error:undefined}));
 const store=local.current,busy=useStore(store,s=>s.busy),error=useStore(store,s=>s.error);
 const run=async(action:Action)=>{if(store.getState().busy)return;store.setState({busy:true,error:undefined});try{await action();props.onClose();}catch(e){store.setState({error:e instanceof Error?e.message:String(e)});}finally{store.setState({busy:false});}};
 const notice=props.notice,styled=!props.unstyled;
 return <Modal visible={props.visible} transparent animationType="none" onRequestClose={()=>{if(!busy)props.onClose();}}>
  <View style={{flex:1,padding:16,alignItems:'center',justifyContent:'center'}} {...{className:styled?'bg-text/50':undefined}}>
   <View accessibilityViewIsModal role="dialog" aria-modal accessibilityLabel={recoveryTitle(notice)} style={{width:'100%',maxWidth:460}} {...{className:joinClasses(styled&&'bg-surface-raised border border-border rounded-card p-4 gap-4',props.className)}}>
    <Text accessibilityRole="header" {...{className:styled?'text-text text-lg font-semibold':undefined}}>{recoveryTitle(notice)}</Text>
    <Text {...{className:styled?'text-text':undefined}}>{recoveryMessage(notice)}</Text>
    {notice.kind==='paused'&&!notice.ready?<Text {...{className:styled?'text-text-muted':undefined}}>Resume is unavailable until the host confirms audio is ready.</Text>:null}
    {error||props.error?<Text accessibilityLiveRegion="polite" {...{className:styled?'text-danger':undefined}}>{error??props.error}</Text>:null}
    <View style={{flexDirection:'row',flexWrap:'wrap',gap:8,justifyContent:'flex-end'}}>
     <Button title="Close" variant="ghost" unstyled={props.unstyled} disabled={busy||props.disabledReason!==undefined} onPress={props.onClose}/>
     {'onKeep' in props?<><Button title="Discard recording" variant="danger" unstyled={props.unstyled} disabled={busy||props.disabledReason!==undefined} onPress={()=>{void run(props.onDiscard);}}/><Button title="Keep recording" unstyled={props.unstyled} disabled={busy||props.disabledReason!==undefined} onPress={()=>{void run(props.onKeep);}}/></>:
      'onRetry' in props?<><Button title="Stop" variant="secondary" unstyled={props.unstyled} disabled={busy||props.disabledReason!==undefined} onPress={()=>{void run(props.onStop);}}/><Button title="Restart audio" unstyled={props.unstyled} disabled={busy||props.disabledReason!==undefined} onPress={()=>{void run(props.onRetry);}}/></>:
      <><Button title="Stop" variant="secondary" unstyled={props.unstyled} disabled={busy||props.disabledReason!==undefined} onPress={()=>{void run(props.onStop);}}/><Button title="Resume" unstyled={props.unstyled} disabled={busy||!props.notice.ready||props.disabledReason!==undefined} onPress={()=>{void run(props.onResume);}}/></>}
    </View>
   </View>
  </View>
 </Modal>;
}

import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}
